-- Flamingo: private backend schema; no access from anon/authenticated Data API.
CREATE SCHEMA flamingo;
SET search_path TO flamingo, pg_catalog;
    CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','cashier')),active INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS inventory(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'ud',stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),minimum INTEGER NOT NULL DEFAULT 5);
    CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),art TEXT NOT NULL,description TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
    CREATE TABLE IF NOT EXISTS recipes(product_id INTEGER REFERENCES products(id),item_id INTEGER REFERENCES inventory(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(product_id,item_id));
    CREATE TABLE IF NOT EXISTS shifts(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),opened_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMPTZ,opening_cash INTEGER NOT NULL,expected_cash INTEGER,counted_cash INTEGER,cash_difference INTEGER,notes TEXT);
    CREATE UNIQUE INDEX IF NOT EXISTS one_open_shift ON shifts((1)) WHERE closed_at IS NULL;
    CREATE TABLE IF NOT EXISTS sales(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id TEXT UNIQUE NOT NULL,shift_id INTEGER NOT NULL REFERENCES shifts(id),user_id INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,total INTEGER NOT NULL,cash INTEGER NOT NULL,qr INTEGER NOT NULL,card INTEGER NOT NULL,tendered INTEGER NOT NULL,change_due INTEGER NOT NULL,service TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'paid',void_reason TEXT);
    CREATE TABLE IF NOT EXISTS sale_lines(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sale_id INTEGER REFERENCES sales(id),product_id INTEGER REFERENCES products(id),name TEXT NOT NULL,quantity INTEGER NOT NULL,price INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS movements(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES inventory(id),quantity INTEGER NOT NULL,kind TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),shift_id INTEGER REFERENCES shifts(id),sale_id INTEGER REFERENCES sales(id),note TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS counts(shift_id INTEGER REFERENCES shifts(id),item_id INTEGER REFERENCES inventory(id),expected INTEGER NOT NULL,counted INTEGER NOT NULL,difference INTEGER NOT NULL,PRIMARY KEY(shift_id,item_id));
    CREATE TABLE IF NOT EXISTS shift_stock(shift_id INTEGER REFERENCES shifts(id),item_id INTEGER REFERENCES inventory(id),opening INTEGER NOT NULL,PRIMARY KEY(shift_id,item_id));
    CREATE TABLE IF NOT EXISTS audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,detail TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS reconciliations(shift_id INTEGER PRIMARY KEY REFERENCES shifts(id),expected_cash INTEGER NOT NULL,started_by INTEGER NOT NULL REFERENCES users(id),frozen_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_by INTEGER REFERENCES users(id),approved_at TIMESTAMPTZ,approval_notes TEXT);
    CREATE TABLE IF NOT EXISTS reconciliation_items(shift_id INTEGER REFERENCES reconciliations(shift_id),item_id INTEGER REFERENCES inventory(id),name TEXT NOT NULL,unit TEXT NOT NULL,opening INTEGER NOT NULL,expected INTEGER NOT NULL,PRIMARY KEY(shift_id,item_id));
    CREATE TABLE IF NOT EXISTS declarations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shift_id INTEGER NOT NULL REFERENCES reconciliations(shift_id),version INTEGER NOT NULL,request_id TEXT UNIQUE NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id),counted_cash INTEGER NOT NULL,notes TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(shift_id,version));
    CREATE TABLE IF NOT EXISTS declaration_items(declaration_id INTEGER REFERENCES declarations(id),item_id INTEGER REFERENCES inventory(id),quantity INTEGER NOT NULL,PRIMARY KEY(declaration_id,item_id));
    CREATE TABLE IF NOT EXISTS recount_requests(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shift_id INTEGER NOT NULL REFERENCES reconciliations(shift_id),version INTEGER NOT NULL,requested_by INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(shift_id,version));
    CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
ALTER TABLE shifts ADD COLUMN stage TEXT NOT NULL DEFAULT 'open' CHECK (stage IN ('open','counting','review','recount','closed'));
ALTER TABLE shifts ADD COLUMN count_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE shifts ADD COLUMN opening_confirmed_at TIMESTAMPTZ;
ALTER TABLE products ADD COLUMN menu_key TEXT;
ALTER TABLE products ADD COLUMN group_name TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN variant TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN size TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN flavor TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN inventory_mode TEXT NOT NULL DEFAULT 'recipe' CHECK (inventory_mode IN ('recipe','untracked'));
ALTER TABLE inventory ADD COLUMN active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1));
CREATE UNIQUE INDEX unique_menu_key ON products(menu_key) WHERE menu_key IS NOT NULL;
ALTER TABLE inventory ADD CONSTRAINT nonnegative_minimum CHECK(minimum>=0);
ALTER TABLE sales ADD CONSTRAINT balanced_payment CHECK(total>0 AND cash>=0 AND qr>=0 AND card>=0 AND cash+qr+card=total AND tendered>=cash AND change_due=tendered-cash);
ALTER TABLE sales ADD CONSTRAINT sale_status CHECK(status IN ('paid','void'));
ALTER TABLE sales ADD CONSTRAINT sale_service CHECK(service IN ('local','takeaway'));
ALTER TABLE shifts ADD CONSTRAINT valid_opening_cash CHECK(opening_cash>=0);
ALTER TABLE sale_lines ADD CONSTRAINT valid_sale_line CHECK(quantity>0 AND price>0);
ALTER TABLE declaration_items ADD CONSTRAINT valid_count CHECK(quantity>=0);
ALTER TABLE declarations ADD CONSTRAINT valid_cash_count CHECK(counted_cash>=0 AND version>0);
ALTER TABLE counts ADD CONSTRAINT balanced_count CHECK(counted>=0 AND difference=counted-expected);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX sessions_expiry_idx ON sessions(expires);
CREATE INDEX recipes_item_idx ON recipes(item_id);
CREATE INDEX shifts_user_idx ON shifts(user_id);
CREATE INDEX sales_shift_idx ON sales(shift_id);
CREATE INDEX sales_user_idx ON sales(user_id,id DESC);
CREATE INDEX sales_paid_date_idx ON sales(created_at) WHERE status='paid';
CREATE INDEX sale_lines_sale_idx ON sale_lines(sale_id);
CREATE INDEX sale_lines_product_idx ON sale_lines(product_id);
CREATE INDEX movements_item_idx ON movements(item_id);
CREATE INDEX movements_user_idx ON movements(user_id);
CREATE INDEX movements_shift_idx ON movements(shift_id);
CREATE INDEX movements_sale_idx ON movements(sale_id);
CREATE INDEX counts_item_idx ON counts(item_id);
CREATE INDEX shift_stock_item_idx ON shift_stock(item_id);
CREATE INDEX audit_user_idx ON audit(user_id);
CREATE INDEX reconciliation_started_idx ON reconciliations(started_by);
CREATE INDEX reconciliation_approved_idx ON reconciliations(approved_by);
CREATE INDEX reconciliation_items_item_idx ON reconciliation_items(item_id);
CREATE INDEX declarations_author_idx ON declarations(author_id);
CREATE INDEX declaration_items_item_idx ON declaration_items(item_id);
CREATE INDEX recount_requests_user_idx ON recount_requests(requested_by);
INSERT INTO settings(key,value) VALUES('schema_version','1');

DO $$ BEGIN
 IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='flamingo_app') THEN CREATE ROLE flamingo_app NOLOGIN; END IF;
END $$;
REVOKE ALL ON SCHEMA flamingo FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA flamingo FROM PUBLIC;
GRANT USAGE ON SCHEMA flamingo TO flamingo_app;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA flamingo TO flamingo_app;
GRANT DELETE ON flamingo.sessions,flamingo.recipes TO flamingo_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA flamingo TO flamingo_app;
ALTER TABLE flamingo.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.users TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.sessions TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.inventory TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.products TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.recipes ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.recipes TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.shifts ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.shifts TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.sales TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.sale_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.sale_lines TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.movements TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.counts ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.counts TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.shift_stock ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.shift_stock TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.audit TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.reconciliations ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.reconciliations TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.reconciliation_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.reconciliation_items TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.declarations ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.declarations TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.declaration_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.declaration_items TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.recount_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.recount_requests TO flamingo_app USING (true) WITH CHECK (true);
ALTER TABLE flamingo.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_access ON flamingo.settings TO flamingo_app USING (true) WITH CHECK (true);

RESET search_path;
